func formatUnitsLabel(qty int64) string {
	s := fmt.Sprintf("%d", qty)
	n := len(s)
	if n > 3 {
		var out []byte
		rem := n % 3
		if rem > 0 {
			out = append(out, s[:rem]...)
		}
		for i := rem; i < n; i += 3 {
			if len(out) > 0 {
				out = append(out, ',')
			}
			out = append(out, s[i:i+3]...)
		}
		s = string(out)
	}
	if qty == 1 {
		return s + " unit"
	}
	return s + " units"
}

